from pybricks.hubs import PrimeHub
from pybricks.iodevices import XboxController
from pybricks.parameters import Button, Direction, Port, Stop
from pybricks.pupdevices import Motor

# Set up.
prime_hub = PrimeHub()
motor2 = Motor(Port.D, Direction.CLOCKWISE)
controller = XboxController()

def closedoor():
    motor2.run_angle(500, -90)
    print('good bye ')

def opendoor():
    motor2.run_angle(500, 90)
    print('Welcome ')


# The main program starts here.
while True:
    if Button.RIGHT in prime_hub.buttons.pressed() or controller.triggers()[1]:
        opendoor()
    if Button.LEFT in prime_hub.buttons.pressed() or controller.triggers()[0]:
        closedoor()
